mapper.select:
SELECT *
FROM execution_items
WHERE user_id    = #{userId}
  AND is_deleted = 0
  AND plan_version_id IN (
        SELECT plan_version_id FROM plan_versions
         WHERE plan_key = #{planKey} AND user_id = #{userId}
      )
  AND (
        scheduled_date BETWEEN #{startDate} AND #{endDate}
     OR (scheduled_date IS NULL
         AND planning_start_date <= #{endDate}
         AND planning_end_date   >= #{startDate})
      )
ORDER BY scheduled_date IS NULL,
         scheduled_date ASC, order_index ASC, execution_item_id ASC

SELECT *
FROM execution_items
WHERE user_id        = #{userId}
  AND is_deleted     = 0
  AND placement_type = 'UNSCHEDULED'
  AND status         = 'PLANNED'
  AND plan_version_id IN (
        SELECT plan_version_id FROM plan_versions
         WHERE plan_key = #{planKey} AND user_id = #{userId}
      )
  AND planning_start_date <= #{windowEnd}
  AND planning_end_date   >= #{windowStart}
ORDER BY priority = 'MUST' DESC, order_index ASC, execution_item_id ASC
